      "title": "Option de paiement de TVA",
      "label": "Obligatoire, pour les prestations de service et les factures doubles (selon codification TT-81 - catégorie de transactions) si l'opérateur a opté pour le paiement de la TVA sur les débits. N.B. : Règle de gestion métier mais ne peut pas être contrôlée d'un point de vue applicatif",
