      "title": "Code de catégorie de TVA",
      "label": "Seuls les codes de catégorie de TVA suivants seront acceptés: S = Taux de TVA standard E = Exonéré de TVA AE = Autoliquidation de TVA K = Exonération pour cause de livraison intracommunautaire G = Exonération de TVA pour Export hors UE O = Hors du périmètre d'application de la TVA Z = Taux de TVA égal à 0 (cf. G1.47) Les codes de catégorie de TVA suivants ne sont pas pertinents en France : L = Iles Canaries M = Ceuta et Mellila",
