      "id": "G7.18",
      "title": "Motif d'irrecevabilité",
      "label": "Liste des codes d'irrecevabilité d'un flux et leur libellé acceptés par le PPF : Codes irrecevabilité du flux suite à des contrôles réalisés flux : - IRR_TAILLE - Contrôle de taille du flux - IRR_UNICITE - Contrôle d'unicité du flux - IRR_VIDE - Contrôle de flux non vide - IRR_FORM - Contrôle de format du nom de l'enveloppe - IRR_TYPE - Contrôle de type et extension du flux - IRR_ANTIVIRUS - Contrôle anti-virus - IRR_CODE_INTER - Code interface inconnu (ici il s’agit d’un code interface qui respecte le format mais qui n’est pas connu du système) - IRR_EXTRAC - L'archive du flux déposé n'a pas pu être extraite - IRR_CODE_APP - Aucun raccordement n'existe pour le code application correspondant au flux déposé Irrecevabilité du flux suite à des contrôles sur les fichiers du flux : - IRR_VIDE_F - Contrôle de non vide sur les fichiers du flux - IRR_TYPE_F - Contrôle de type et extension des fichiers du flux - IRR_SYNTAX - Contrôle syntaxique des fichiers du flux - IRR_TAILLE_PJ - Contrôle de taille des PJ de chaque fichier du flux - IRR_NOM_PJ - Contrôle du nom des PJ de chaque fichier du flux (absence de caractères interdits) - IRR_VID_PJ - Contrôle de PJ non vide de chaque fichier du flux - IRR_EXT_DOC - Contrôle de l'extension des PJ de chaque fichier du flux - IRR_TAILLE_F - Contrôle de taille max des fichiers contenus dans le flux - IRR_NOM_F - Contrôle du nom de fichier contenus dans le flux",
