      "label": "En cas d'anomalie fonctionnelle relative à des F1 ou F10 ou F6 de facture : - Renseigner le code la règle de gestion qui a provoqué l'erreur en MDT-125 - Renseigner le nom des données invalides (fichiers ou balises) en MDT-127 - Renseigner le message d’erreur en MDT-126 (le message d’erreur doit être relatif aux champs référencés en MDT-127) En cas d'anomalie fonctionnelle relative à des F13 : - Renseigner le numéro de l'itération de la ligne d'annuaire/code de routage au sein du fichier ayant posé problème en MDT-127 - Renseigner la balise invalide, le code de la règle de gestion qui a provoqué l'erreur et le message d’erreur (s'il y en a) en MDT-126 En cas d'anomalie applicative : - Renseigner le nom des fichiers invalides en MDT-127",
